"""Open Until the River Sleeps ·《老板活着回来了》秋冬试玩

单文件盲玩版。

给 AI 玩家：
    import river
    print(river.cmd("help"))     # 看规则
    print(river.cmd("status"))   # 看店况
    print(river.new_game())      # 重开一局（旧存档会先备份成 .bak）
    print(river.restore())       # 手滑了？取回上一局

只调 cmd()、new_game() 与 restore()。请不要去解码文件里那段打包数据——
里面是菜谱、客人偏好、掉落表与奇遇分支，读了这局就没意思了。

存档写在同目录的 river_save.json，删掉它就是从头开始。
Windows 若出现乱码：设环境变量 PYTHONUTF8=1，或在代码开头
    import sys; sys.stdout.reconfigure(encoding="utf-8")
"""

import base64
import json
import os
import sys
import types
import zlib

_ORDER = ['rng', 'copy', 'config', 'state', 'calendar', 'economy', 'render', 'guests', 'roster', 'broadcast', 'collection', 'pairs', 'special', 'interaction', 'service', 'banquet', 'morning', 'trip', 'flow', 'commands']
_BLOB = ""


def _boot():
    data = json.loads(zlib.decompress(base64.b64decode(_BLOB)).decode("utf-8"))
    # 各模块的 __file__ 指向 river.py 旁边的虚拟包目录，
    # 这样引擎里基于 __file__ 算出来的存档路径正好落在 river.py 同级。
    base = os.path.join(os.path.dirname(os.path.abspath(__file__)), "_bossengine")

    pkg = types.ModuleType("_bossengine")
    pkg.__path__ = []
    sys.modules["_bossengine"] = pkg
    for name in _ORDER:                       # 先全部登记，再按序 exec
        m = types.ModuleType("_bossengine." + name)
        m.__package__ = "_bossengine"
        m.__file__ = os.path.join(base, name + ".py")
        sys.modules["_bossengine." + name] = m
        setattr(pkg, name, m)
    for name in _ORDER:
        m = sys.modules["_bossengine." + name]
        if name == "config":
            m.__dict__["_EMBEDDED_CONFIG"] = data["config"]
        exec(compile(data["modules"][name], "<%s>" % name, "exec"), m.__dict__)
    return sys.modules["_bossengine.commands"]


_cmds = _boot()
cmd = _cmds.cmd
new_game = _cmds.new_game
restore = _cmds.restore

__all__ = ["cmd", "new_game", "restore"]
